#!/usr/bin/env node
// Build the "Run it locally" section of each repos/<name>/ONBOARDING.md from
// repos/<name>/run-locally.json. The section sits between the BEGIN and END markers; the rest
// of ONBOARDING.md comes from /understand-onboard. A regenerated ONBOARDING.md has no markers:
// this script then inserts the section after the first section (the project overview).
// Usage: node build-onboarding.mjs           rewrite the section in every ONBOARDING.md
//        node build-onboarding.mjs --check   exit 1 if a section is missing or stale (CI)
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { loadEstate, root } from "./estate.mjs";

const BEGIN = (name) =>
  `<!-- BEGIN run it locally: generated by .github/scripts/build-onboarding.mjs from repos/${name}/run-locally.json. Do not edit by hand. -->`;
const END = "<!-- END run it locally -->";

const check = process.argv.includes("--check");
const { areas, errors } = loadEstate();
const repos = areas.flatMap((a) => a.repos);

// Check one run-locally.json. Report every problem; return true if the file is usable.
function validate(name, spec, sha) {
  const at = `repos/${name}/run-locally.json`;
  const before = errors.length;
  const isText = (v) => typeof v === "string" && v.trim() !== "";
  const isList = (v) => Array.isArray(v) && v.length > 0 && v.every(isText);
  const known = ["sourceCommit", "sources", "intro", "prerequisites", "steps"];
  for (const key of Object.keys(spec)) if (!known.includes(key)) errors.push(`${at}: unknown key "${key}"`);
  if (spec.sourceCommit !== sha) {
    errors.push(
      `${at}: sourceCommit does not match meta.json (${sha}). Check the steps against the source at that commit, then update sourceCommit.`,
    );
  }
  if (!isList(spec.sources)) errors.push(`${at}: sources must be a non-empty list of paths in the source repo`);
  else for (const p of spec.sources) if (/^\/|(^|\/)\.\.?(\/|$)|[\u0000-\u001f`]/.test(p)) errors.push(`${at}: source "${p}" is not a plain repo path`);
  if (spec.intro !== undefined && !isText(spec.intro)) errors.push(`${at}: intro must be text`);
  if (!isList(spec.prerequisites)) errors.push(`${at}: prerequisites must be a non-empty list of text`);
  if (!Array.isArray(spec.steps) || spec.steps.length === 0) errors.push(`${at}: steps must be a non-empty list`);
  else {
    spec.steps.forEach((step, i) => {
      const s = `${at}: steps[${i}]`;
      for (const key of Object.keys(step)) if (!["title", "text", "lang", "code"].includes(key)) errors.push(`${s}: unknown key "${key}"`);
      if (!isText(step.title)) errors.push(`${s}: title must be text`);
      if (step.text !== undefined && !isText(step.text)) errors.push(`${s}: text must be text`);
      if (step.code !== undefined && !isList(step.code)) errors.push(`${s}: code must be a non-empty list of lines`);
      if (step.lang !== undefined && !/^[a-z]+$/.test(step.lang)) errors.push(`${s}: lang must be a lowercase word`);
      if (step.lang !== undefined && step.code === undefined) errors.push(`${s}: lang needs code`);
      if (step.text === undefined && step.code === undefined) errors.push(`${s}: needs text, code, or both`);
    });
  }
  return errors.length === before;
}

// The section. Step 1 ("Get the code") is the same for every repo, so the script writes it.
function render({ name, sha, source }, spec) {
  const blob = (path) => `[\`${path}\`](${source}/blob/${sha}/${path.split("/").map(encodeURIComponent).join("/")})`;
  const steps = [
    {
      title: "Get the code",
      text: "To contribute, fork the repo on GitHub first, then clone your fork instead.",
      code: [`git clone ${source}.git`, `cd ${name}`],
    },
    ...spec.steps,
  ];
  const lines = [
    "## Run it locally",
    "",
    `> These steps come from the files below, at commit [\`${sha.slice(0, 7)}\`](${source}/commit/${sha}) of the source repo.`,
    `> The source [README](${source}#readme) is the source of truth: verify each command against it.`,
    ">",
    `> Sources: ${spec.sources.map(blob).join(", ")}`,
    "",
  ];
  if (spec.intro) lines.push(spec.intro, "");
  lines.push("**Prerequisites:**", "", ...spec.prerequisites.map((p) => `- ${p}`), "");
  steps.forEach((step, i) => {
    lines.push(`### ${i + 1}. ${step.title}`, "");
    if (step.text) lines.push(step.text, "");
    if (step.code) lines.push(`\`\`\`${step.lang ?? "bash"}`, ...step.code, "```", "");
  });
  return lines.join("\n").trimEnd();
}

// Put the section between the markers, or insert it before the second "## " heading.
function splice(name, doc, section) {
  const begin = BEGIN(name);
  const block = `${begin}\n\n${section}\n\n${END}`;
  const start = doc.indexOf(begin);
  const stop = doc.indexOf(END);
  if (start >= 0 && stop > start) return doc.slice(0, start) + block + doc.slice(stop + END.length);
  if (start >= 0 || stop >= 0) return errors.push(`repos/${name}/ONBOARDING.md: one marker is missing`), null;
  const headings = [...doc.matchAll(/^## /gm)];
  if (headings.length < 2) return errors.push(`repos/${name}/ONBOARDING.md: needs two "## " sections to place the section`), null;
  const at = headings[1].index;
  return `${doc.slice(0, at)}${block}\n\n${doc.slice(at)}`;
}

const updates = [];
for (const repo of repos) {
  const specPath = join(root, "repos", repo.name, "run-locally.json");
  const docPath = join(root, "repos", repo.name, "ONBOARDING.md");
  if (!existsSync(specPath)) {
    errors.push(`repos/${repo.name}/run-locally.json is missing`);
    continue;
  }
  if (!existsSync(docPath)) continue; // loadEstate() already reports it
  let spec;
  try {
    spec = JSON.parse(readFileSync(specPath, "utf8"));
  } catch (e) {
    errors.push(`repos/${repo.name}/run-locally.json: ${e.message}`);
    continue;
  }
  if (!validate(repo.name, spec, repo.sha)) continue;
  const doc = readFileSync(docPath, "utf8");
  const next = splice(repo.name, doc, render(repo, spec));
  if (next !== null && next !== doc) updates.push({ name: repo.name, docPath, next });
}

if (errors.length) {
  for (const e of errors) console.error(`error: ${e}`);
  process.exit(1);
}

if (check) {
  if (updates.length) {
    for (const u of updates) console.error(`error: repos/${u.name}/ONBOARDING.md: the Run it locally section is missing or stale`);
    console.error("Run: node .github/scripts/build-onboarding.mjs");
    process.exit(1);
  }
  console.log(`Run it locally sections are current (${repos.length} repos)`);
} else {
  for (const u of updates) writeFileSync(u.docPath, u.next);
  console.log(`wrote the Run it locally section to ${updates.length} of ${repos.length} ONBOARDING.md files`);
}
